<?php
require_once __DIR__ . '/functions.php';
$pdo=db();$id=(int)($_GET['id']??0);
$stmt=$pdo->prepare("SELECT p.*,c.title category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.status='active' LIMIT 1");$stmt->execute([$id]);$p=$stmt->fetch();
if(!$p){http_response_code(404);exit('Product not found');}
$pd=product_price_data($p);
$reviewsStmt=$pdo->prepare("SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? ORDER BY r.created_at DESC");$reviewsStmt->execute([$id]);$reviews=$reviewsStmt->fetchAll();
$rating=$reviews?round(array_sum(array_column($reviews,'rating'))/count($reviews),1):0;
$relatedStmt=$pdo->prepare("SELECT p.*,c.title category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.category_id=? AND p.id<>? AND p.status='active' ORDER BY p.created_at DESC LIMIT 4");$relatedStmt->execute([$p['category_id'],$id]);$related=$relatedStmt->fetchAll();
$title=$p['name'];include __DIR__.'/partials/header.php';
?>
