    <div class="detail-pro-content"><span class="badge"><?=e($p['category'])?></span><h1><?=e($p['name'])?></h1><div class="rating-line"><span class="stars"><?=str_repeat('★',(int)round($rating))?><?=str_repeat('☆',5-(int)round($rating))?></span><span><?=number_format($rating,1)?> · <?=count($reviews)?> reviews</span></div>
      <div class="detail-price"><strong><?=money($p['price'])?></strong><?php if($pd['discount']):?><del><?=money($pd['compare_price'])?></del><span><?=$pd['discount']?>% OFF</span><?php endif;?></div>
