      <p class="detail-description"><?=nl2br(e($p['content']))?></p>
      <div class="feature-strip"><div><b>✓</b><span>Authentic product</span></div><div><b>✓</b><span>Home delivery</span></div><div><b>✓</b><span>Secure checkout</span></div></div>
      <?php if((int)$p['stock']>0):?><form method="post" action="<?=BASE_URL?>/cart.php" class="buy-box"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$id?>"><label>Quantity<input name="quantity" type="number" min="1" max="<?=$p['stock']?>" value="1"></label><button class="btn btn-primary">Add to Cart</button></form><form method="post" action="<?=BASE_URL?>/cart.php" class="buy-now-inline"><?=csrf_field()?><input type="hidden" name="action" value="buy_now"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="quantity" value="1"><button class="btn btn-dark">Buy Now</button></form><?php else:?><div class="notice">This product is currently out of stock.</div><?php endif;?>
