  <div class="detail-lower"><section class="panel"><div class="section-head"><div><span class="eyebrow">PRODUCT INFORMATION</span><h2>Details</h2></div></div><div class="spec-grid"><div><span>Category</span><b><?=e($p['category'])?></b></div><div><span>Delivery</span><b><?=e($p['delivery_kind'])?></b></div><div><span>Availability</span><b><?=((int)$p['stock']>0?'In stock':'Out of stock')?></b></div><div><span>Product ID</span><b>#<?=e($p['id'])?></b></div></div><div class="long-description"><?=nl2br(e($p['content']))?></div></section>
    <section class="panel"><div class="section-head"><div><span class="eyebrow">CUSTOMER FEEDBACK</span><h2>Reviews</h2></div><span class="muted"><?=count($reviews)?> review(s)</span></div><?php if(is_logged_in() && user()['role']==='buyer'):?><form method="post" action="<?=BASE_URL?>/review.php" class="form-grid"><input type="hidden" name="product_id" value="<?=$id?>"><?=csrf_field()?><div class="field"><label>Rating</label><select name="rating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></div><div class="field full"><label>Your review</label><textarea name="comment" rows="3" required></textarea></div><button class="btn btn-primary">Submit Review</button></form><hr><?php endif;?><?php foreach($reviews as $r):?><div class="review-row"><div><b><?=e($r['name'])?></b><span class="stars"><?=str_repeat('★',(int)$r['rating'])?></span></div><p><?=e($r['comment'])?></p><small><?=e($r['created_at'])?></small></div><?php endforeach;?><?php if(!$reviews):?><p class="muted">No reviews yet. Be the first to review this product.</p><?php endif;?></section>
